{
  "extracted_concepts": [
    {
      "name": "Sample Space",
      "aliases": ["sample space", "样本空间"],
      "definition_snippet": "Set Ω of all possible outcomes of a random experiment.",
      "category": "concept"
    },
    {
      "name": "Event",
      "aliases": ["event", "事件"],
      "definition_snippet": "Subset of the sample space.",
      "category": "concept"
    },
    {
      "name": "Probability Axioms",
      "aliases": ["probability axioms", "概率公理"],
      "definition_snippet": "Nonnegativity, normalization, and countable additivity.",
      "category": "property"
    },
    {
      "name": "Classical Probability Model",
      "aliases": ["classical probability model", "古典概型"],
      "definition_snippet": "P(A)=|A|/|Ω| when outcomes are equally likely.",
      "category": "concept"
    },
    {
      "name": "Conditional Probability",
      "aliases": ["conditional probability", "条件概率"],
      "definition_snippet": "P(B|A)=P(AB)/P(A).",
      "category": "operation"
    },
    {
      "name": "Bayes' Theorem",
      "aliases": ["Bayes theorem", "贝叶斯定理"],
      "definition_snippet": "Updates P(A_j|B) using prior probabilities and likelihoods.",
      "category": "theorem"
    },
    {
      "name": "Independence of Events",
      "aliases": ["independence of events", "事件独立性"],
      "definition_snippet": "P(AB)=P(A)P(B).",
      "category": "property"
    },
    {
      "name": "Random Variable",
      "aliases": ["random variable", "随机变量"],
      "definition_snippet": "Function X: Ω → ℝ.",
      "category": "concept"
    },
    {
      "name": "Probability Mass Function",
      "aliases": ["PMF", "概率质量函数"],
      "definition_snippet": "P(X=x_k)=p_k for discrete X.",
      "category": "concept"
    },
    {
      "name": "Binomial Distribution",
      "aliases": ["binomial distribution", "二项分布"],
      "definition_snippet": "Distribution B(n,p) of number of successes.",
      "category": "concept"
    },
    {
      "name": "Poisson Distribution",
      "aliases": ["Poisson distribution", "泊松分布"],
      "definition_snippet": "Discrete distribution P(λ) for rare-event counts.",
      "category": "concept"
    },
    {
      "name": "Probability Density Function",
      "aliases": ["PDF", "概率密度函数"],
      "definition_snippet": "f(x)≥0 and ∫f(x)dx=1 for continuous X.",
      "category": "concept"
    },
    {
      "name": "Cumulative Distribution Function",
      "aliases": ["CDF", "累积分布函数"],
      "definition_snippet": "F(x)=P(X≤x).",
      "category": "concept"
    },
    {
      "name": "Normal Distribution",
      "aliases": ["normal distribution", "正态分布"],
      "definition_snippet": "Continuous distribution N(μ,σ²).",
      "category": "concept"
    },
    {
      "name": "Transformation of Random Variable",
      "aliases": ["transformation of random variable", "随机变量变换"],
      "definition_snippet": "Find distribution of Y=g(X) via CDF or transformation formula.",
      "category": "operation"
    },
    {
      "name": "Joint Distribution",
      "aliases": ["joint distribution", "联合分布"],
      "definition_snippet": "F(x,y)=P(X≤x,Y≤y) or joint PDF f(x,y).",
      "category": "concept"
    },
    {
      "name": "Marginal Distribution",
      "aliases": ["marginal distribution", "边缘分布"],
      "definition_snippet": "Obtain f_X or f_Y by integrating the joint density.",
      "category": "concept"
    },
    {
      "name": "Independence of Random Variables",
      "aliases": ["independence of random variables", "随机变量独立性"],
      "definition_snippet": "f(x,y)=f_X(x)f_Y(y).",
      "category": "property"
    },
    {
      "name": "Convolution",
      "aliases": ["convolution", "卷积"],
      "definition_snippet": "Density of Z=X+Y via f_Z(z)=∫f(x,z-x)dx.",
      "category": "operation"
    },
    {
      "name": "Expectation",
      "aliases": ["expectation", "期望"],
      "definition_snippet": "E(X)=∫xf(x)dx or Σx_kp_k.",
      "category": "operation"
    },
    {
      "name": "Variance",
      "aliases": ["variance", "方差"],
      "definition_snippet": "Var(X)=E[(X-μ)²]=E(X²)-[E(X)]².",
      "category": "operation"
    },
    {
      "name": "Covariance",
      "aliases": ["covariance", "协方差"],
      "definition_snippet": "Cov(X,Y)=E(XY)-E(X)E(Y).",
      "category": "operation"
    },
    {
      "name": "Correlation Coefficient",
      "aliases": ["correlation coefficient", "相关系数"],
      "definition_snippet": "ρ=Cov(X,Y)/√(Var(X)Var(Y)).",
      "category": "property"
    },
    {
      "name": "Law of Large Numbers",
      "aliases": ["law of large numbers", "大数定律"],
      "definition_snippet": "Sample mean converges to μ.",
      "category": "theorem"
    },
    {
      "name": "Central Limit Theorem",
      "aliases": ["central limit theorem", "中心极限定理"],
      "definition_snippet": "Standardized sums converge to N(0,1).",
      "category": "theorem"
    },
    {
      "name": "Sample Mean",
      "aliases": ["sample mean", "样本均值"],
      "definition_snippet": "X̄ averages sample observations.",
      "category": "concept"
    },
    {
      "name": "Sample Variance",
      "aliases": ["sample variance", "样本方差"],
      "definition_snippet": "S² measures sample dispersion.",
      "category": "concept"
    },
    {
      "name": "Chi-square Distribution",
      "aliases": ["chi-square distribution", "卡方分布"],
      "definition_snippet": "Distribution used for normal variance inference.",
      "category": "concept"
    },
    {
      "name": "t Distribution",
      "aliases": ["t distribution", "t分布"],
      "definition_snippet": "Distribution used when σ is unknown.",
      "category": "concept"
    },
    {
      "name": "Method of Moments",
      "aliases": ["method of moments", "矩估计法"],
      "definition_snippet": "Estimate parameters by equating sample and population moments.",
      "category": "operation"
    },
    {
      "name": "Maximum Likelihood Estimation",
      "aliases": ["MLE", "最大似然估计"],
      "definition_snippet": "Maximize L(θ)=Πf(x_i;θ).",
      "category": "operation"
    },
    {
      "name": "Unbiasedness",
      "aliases": ["unbiasedness", "无偏性"],
      "definition_snippet": "E(θ̂)=θ.",
      "category": "property"
    },
    {
      "name": "Consistency",
      "aliases": ["consistency", "相合性"],
      "definition_snippet": "θ̂ converges in probability to θ.",
      "category": "property"
    },
    {
      "name": "Confidence Interval",
      "aliases": ["confidence interval", "置信区间"],
      "definition_snippet": "Interval estimate such as X̄ ± margin.",
      "category": "concept"
    },
    {
      "name": "Hypothesis Testing",
      "aliases": ["hypothesis testing", "假设检验"],
      "definition_snippet": "Decide between H₀ and H₁ using a test statistic.",
      "category": "concept"
    },
    {
      "name": "Z-test",
      "aliases": ["Z-test", "Z检验"],
      "definition_snippet": "Test for mean with known σ.",
      "category": "operation"
    },
    {
      "name": "t-test",
      "aliases": ["t-test", "t检验"],
      "definition_snippet": "Test for mean with unknown σ.",
      "category": "operation"
    }
  ],
